"""Validators over depot harness outputs, continued from validators.py.

Each validator takes the collected items and returns (passed, measured).
"""

from __future__ import annotations

from typing import Any

# Inclusive bounds for supplier reliability.
# ASSUMPTION: 0..100. Not given in the spec; pending owner confirmation.
RELIABILITY_MIN: int = 0
RELIABILITY_MAX: int = 100


def _exceeds_capacity(entry: dict[str, Any]) -> bool:
    return entry["max_units"] > entry["capacity"]


def _unnotified_expiries(entry: dict[str, Any]) -> list[tuple]:
    """Expired [sku, wh, qty] triples in one entry with no matching notification."""
    notified = {tuple(item) for item in entry["notified"]}
    return [tuple(item) for item in entry["expired"] if tuple(item) not in notified]


def _reliability_in_range(entry: dict[str, Any]) -> bool:
    return RELIABILITY_MIN <= entry["reliability"] <= RELIABILITY_MAX


def v7(items: list[dict[str, Any]]) -> tuple[bool, object]:
    """V7: every warehouse's capacity was respected across runs.

    measured: list of wh names where max_units exceeded capacity.
    """
    over = [entry["wh"] for entry in items if _exceeds_capacity(entry)]
    return (len(over) == 0, over)


def v8(items: list[dict[str, Any]]) -> tuple[bool, object]:
    """V8: all expiries were notified.

    An expiry counts as notified only if the same [sku, wh, qty] triple
    appears in the same entry's notified list.

    measured: list of (sku, wh, qty) expiries that were not notified.
    """
    missing: list[tuple] = []
    for entry in items:
        missing.extend(_unnotified_expiries(entry))
    return (len(missing) == 0, missing)


def v9(items: list[dict[str, Any]]) -> tuple[bool, object]:
    """V9: every supplier's reliability stayed in range.

    measured: list of supplier names whose reliability fell outside
    RELIABILITY_MIN..RELIABILITY_MAX (inclusive).
    """
    out_of_range = [
        entry["supplier"] for entry in items if not _reliability_in_range(entry)
    ]
    return (len(out_of_range) == 0, out_of_range)
