import unittest

from validators_later import RELIABILITY_MAX, RELIABILITY_MIN, v7, v8, v9


class TestV7(unittest.TestCase):
    def test_passes_when_within_capacity(self):
        items = [
            {"wh": "A", "capacity": 10, "max_units": 10},
            {"wh": "B", "capacity": 5, "max_units": 0},
        ]
        self.assertEqual(v7(items), (True, []))

    def test_fails_and_reports_warehouse_over_capacity(self):
        items = [
            {"wh": "A", "capacity": 10, "max_units": 11},
            {"wh": "B", "capacity": 5, "max_units": 5},
        ]
        self.assertEqual(v7(items), (False, ["A"]))

    def test_empty_input_passes(self):
        self.assertEqual(v7([]), (True, []))


class TestV8(unittest.TestCase):
    def test_passes_when_all_expiries_notified(self):
        items = [
            {
                "expired": [["s1", "w1", 3]],
                "notified": [["s1", "w1", 3], ["s2", "w1", 1]],
            }
        ]
        self.assertEqual(v8(items), (True, []))

    def test_fails_and_reports_missing_expiry(self):
        items = [
            {
                "expired": [["s1", "w1", 3], ["s2", "w2", 4]],
                "notified": [["s1", "w1", 3]],
            }
        ]
        self.assertEqual(v8(items), (False, [("s2", "w2", 4)]))

    def test_quantity_mismatch_counts_as_unnotified(self):
        items = [{"expired": [["s1", "w1", 3]], "notified": [["s1", "w1", 2]]}]
        self.assertEqual(v8(items), (False, [("s1", "w1", 3)]))

    def test_notification_in_other_entry_does_not_count(self):
        items = [
            {"expired": [["s1", "w1", 3]], "notified": []},
            {"expired": [], "notified": [["s1", "w1", 3]]},
        ]
        self.assertEqual(v8(items), (False, [("s1", "w1", 3)]))


class TestV9(unittest.TestCase):
    def test_passes_at_both_bounds(self):
        items = [
            {"supplier": "lo", "reliability": RELIABILITY_MIN},
            {"supplier": "hi", "reliability": RELIABILITY_MAX},
        ]
        self.assertEqual(v9(items), (True, []))

    def test_fails_and_reports_out_of_range_suppliers(self):
        items = [
            {"supplier": "ok", "reliability": 50},
            {"supplier": "low", "reliability": RELIABILITY_MIN - 1},
            {"supplier": "high", "reliability": RELIABILITY_MAX + 1},
        ]
        self.assertEqual(v9(items), (False, ["low", "high"]))

    def test_empty_input_passes(self):
        self.assertEqual(v9([]), (True, []))


if __name__ == "__main__":
    unittest.main()
